/* GERADO por scripts/dividir-dados.js — não edite à mão.
   A fonte editável continua sendo js/data*.js. */
registrarDetalhes({"DH-001":{"cognitivo":{"motivo":"Características clássicas dos direitos humanos + relatividade.","mede":"Teoria geral dos direitos humanos (item 1 do edital).","pegadinhaDesc":"A parte final parece contradizer a lista solene do início — mas está correta.","ondeErra":"Marca E achando que irrenunciável e imprescritível implicariam caráter absoluto.","palavraCritica":"limitação recíproca","tecnica":"Titular não pode renunciar nem o tempo apagar — mas o EXERCÍCIO pode ser limitado por outros direitos.","regraMental":"Direitos humanos: absolutos NÃO; relativos SIM (ponderação)."},"comentario":{"resolucao":"CERTO. A doutrina consagra universalidade (valem para todos), indivisibilidade (formam bloco único), imprescritibilidade (não se perdem pelo tempo) e irrenunciabilidade. A relatividade/limitabilidade convive com essas notas: colisões resolvem-se por ponderação.","fundamento":"Doutrina de direitos humanos; jurisprudência do STF sobre relatividade.","macete":"UIII + R: Universal, Indivisível, Imprescritível, Irrenunciável — e Relativo no exercício.","erroComum":"Confundir irrenunciabilidade (não abrir mão da titularidade) com impossibilidade de restrição.","comoBancaPensa":"Une duas verdades que parecem se contradizer — quem estudou por lista decorada trava."}},"DH-002":{"cognitivo":{"motivo":"Literalidade do art. 5º, § 3º, com o rito trocado pelo de lei complementar.","mede":"Incorporação qualificada de tratados de direitos humanos.","pegadinhaDesc":"Substitui 'dois turnos' e 'três quintos' por 'turno único' e 'maioria absoluta'.","ondeErra":"Valida o conjunto sem conferir os dois números do rito.","palavraCritica":"dois turnos / três quintos","tecnica":"Rito de EC: 2 Casas × 2 turnos × 3/5. Qualquer outro quórum = item errado.","regraMental":"Tratado-emenda = 2-2-3/5 (o mesmo caminho da emenda constitucional)."},"comentario":{"resolucao":"ERRADO. CF, art. 5º, § 3º: os tratados de direitos humanos aprovados 'em cada Casa do Congresso Nacional, em DOIS TURNOS, por TRÊS QUINTOS dos votos dos respectivos membros' equivalem às emendas constitucionais. Maioria absoluta em turno único é rito de lei complementar.","fundamento":"CF, art. 5º, § 3º (EC 45/2004).","macete":"Se equivale a emenda, precisa suar como emenda: 3/5 em dois turnos.","erroComum":"Misturar quóruns de espécies normativas diferentes.","comoBancaPensa":"Pegadinha numérica pura — números e quóruns são sempre o alvo."}},"DH-003":{"cognitivo":{"motivo":"Cobrar o efeito paralisante do Pacto de São José (status supralegal) sobre a prisão do depositário infiel.","mede":"Hierarquia dos tratados de DH e Súmula Vinculante 25.","pegadinhaDesc":"A premissa é verdadeira (a CF prevê) — a conclusão é falsa (a prisão é ilícita).","ondeErra":"Raciocina só com o texto constitucional, ignorando o bloco convencional.","palavraCritica":"ilícita (SV 25)","tecnica":"CADH (art. 7.7) admite prisão por dívida só do devedor de alimentos; com status supralegal, paralisou a legislação do depositário infiel.","regraMental":"Prisão civil no Brasil: SÓ alimentos. Depositário infiel: nunca mais (SV 25)."},"comentario":{"resolucao":"ERRADO. Súmula Vinculante 25/STF: 'É ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade do depósito.' Embora a CF (art. 5º, LXVII) a mencione, o Pacto de São José da Costa Rica — com status supralegal (RE 466.343) — paralisou a eficácia da legislação infraconstitucional que a regulamentava.","fundamento":"CF, art. 5º, LXVII; CADH, art. 7.7; STF, RE 466.343; Súmula Vinculante 25.","macete":"A CF 'permite', mas sem lei válida abaixo dela, a prisão não se executa — efeito paralisante.","erroComum":"Achar que previsão constitucional expressa basta para a licitude.","comoBancaPensa":"Cruza texto constitucional com bloco de convencionalidade — o padrão 'juris + lei' favorito."}},"DH-004":{"cognitivo":{"motivo":"Literalidade do art. 7.7 da CADH, expressamente citada no edital.","mede":"Direito à liberdade pessoal na CADH.","pegadinhaDesc":"Item literal correto — a banca costuma trocar a ressalva (ex.: incluir depositário infiel).","ondeErra":"Desconfia da única exceção e marca E.","palavraCritica":"ressalvados... alimentar","tecnica":"A CADH admite UMA única prisão por dívida: a do devedor de alimentos.","regraMental":"Pacto de São José: dívida não prende — exceto pensão alimentícia."},"comentario":{"resolucao":"CERTO. CADH, art. 7.7: 'Ninguém deve ser detido por dívidas. Este princípio não limita os mandados de autoridade judiciária competente expedidos em virtude de inadimplemento de obrigação alimentar.'","fundamento":"Convenção Americana sobre Direitos Humanos, art. 7.7; Decreto 678/1992.","macete":"Uma exceção só — quem alimenta a exceção é a pensão.","erroComum":"Incluir o depositário infiel na ressalva convencional (a CADH nunca o previu).","comoBancaPensa":"Cobra a literalidade da única exceção — terreno ideal para a troca de conteúdo da ressalva."}},"DH-005":{"cognitivo":{"motivo":"Inversão espelhada das duas primeiras dimensões de direitos.","mede":"Evolução histórica dos direitos humanos.","pegadinhaDesc":"As descrições estão corretas, mas com os rótulos trocados entre si.","ondeErra":"Lê definições familiares sem conferir o pareamento dimensão↔valor.","palavraCritica":"igualdade / liberdade","tecnica":"Monte o trio antes de ler: 1ª=Liberdade (abstenção), 2ª=Igualdade (prestação), 3ª=Fraternidade (difusos).","regraMental":"Lema da Revolução Francesa na ordem: Liberté (1ª), Égalité (2ª), Fraternité (3ª)."},"comentario":{"resolucao":"ERRADO. É o inverso: a 1ª dimensão (direitos civis e políticos) liga-se à LIBERDADE e exige abstenção estatal (status negativo); a 2ª dimensão (direitos sociais, econômicos e culturais) liga-se à IGUALDADE e demanda prestações positivas.","fundamento":"Doutrina — teoria das dimensões/gerações (Karel Vasak; Bobbio).","macete":"1ª: Estado fica LONGE. 2ª: Estado ENTREGA. 3ª: TODOS juntos (paz, meio ambiente, consumidor).","erroComum":"Aceitar o item porque cada metade, isolada, 'existe' na teoria.","comoBancaPensa":"Par conceitual espelhado = inversão simétrica, o mesmo DNA de DA-005."}},"DH-006":{"cognitivo":{"motivo":"Cobrar as características dos direitos humanos.","mede":"Teoria geral dos DH (item 1 do edital).","pegadinhaDesc":"Item correto; a banca costuma trocar por 'prescritíveis' ou confundir com 'inalienáveis'.","ondeErra":"Confunde imprescritibilidade (tempo) com irrenunciabilidade (vontade) ou inalienabilidade (transferência).","palavraCritica":"não se perdem pelo tempo","tecnica":"Imprescritível = não caduca. Inalienável = não se vende/transfere. Irrenunciável = não se abre mão.","regraMental":"DH são universais, indivisíveis, imprescritíveis, inalienáveis, irrenunciáveis — e RELATIVOS (não absolutos)."},"comentario":{"resolucao":"CERTO. A imprescritibilidade é característica dos direitos humanos: eles não se extinguem pelo decurso do tempo nem pelo não uso. Não confundir com inalienabilidade (não podem ser transferidos) e irrenunciabilidade (não se pode renunciar a eles).","fundamento":"Teoria geral dos direitos humanos (doutrina).","macete":"Imprescritível = 'o tempo não apaga'. Diferente de inalienável e irrenunciável.","erroComum":"Misturar as características entre si ou afirmar que DH são absolutos.","comoBancaPensa":"Lista de características é cobrada trocando os conceitos entre si."}},"DH-007":{"cognitivo":{"motivo":"Cobrar a Súmula Vinculante 25 e o efeito do Pacto de São José (Decreto 678/1992).","mede":"Convenção Americana / DH na CF (itens 6 do edital).","pegadinhaDesc":"Mantém a prisão do depositário infiel, que foi afastada pela jurisprudência.","ondeErra":"Aplica a literalidade do art. 5º, LXVII, da CF sem o filtro do controle de convencionalidade.","palavraCritica":"depositário infiel (não cabe)","tecnica":"Só cabe prisão civil do DEVEDOR DE ALIMENTOS. Depositário infiel: proibido (SV 25).","regraMental":"Pacto de São José + SV 25: única prisão civil admitida é a do devedor de alimentos."},"comentario":{"resolucao":"ERRADO. Súmula Vinculante 25/STF: 'É ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade do depósito.' Por força do Pacto de São José (status supralegal), subsiste apenas a prisão civil do devedor voluntário e inescusável de alimentos.","fundamento":"CF, art. 5º, LXVII; Decreto 678/1992 (Pacto de São José); Súmula Vinculante 25/STF.","macete":"Prisão civil hoje = só quem não paga pensão alimentícia.","erroComum":"Admitir a prisão do depositário infiel pela leitura isolada da CF.","comoBancaPensa":"Cruza CF + tratado de DH + súmula — o controle de convencionalidade é o ponto."}},"DH-008":{"cognitivo":{"motivo":"Cobrar a correspondência entre dimensões e valores da Revolução Francesa.","mede":"Afirmação histórica dos DH (item 2).","pegadinhaDesc":"Atribui à 1ª dimensão o conteúdo da 2ª (direitos sociais / igualdade).","ondeErra":"Troca liberdade (1ª) por igualdade (2ª).","palavraCritica":"primeira dimensão = liberdade (não igualdade)","tecnica":"1ª = Liberdade (civis/políticos, prestação negativa). 2ª = Igualdade (sociais, prestação positiva). 3ª = Fraternidade (difusos).","regraMental":"Liberté, Égalité, Fraternité = 1ª, 2ª, 3ª dimensões, nessa ordem."},"comentario":{"resolucao":"ERRADO. A primeira dimensão abrange os direitos civis e políticos (liberdade), com prestação NEGATIVA do Estado. Os direitos sociais, econômicos e culturais (igualdade, prestação positiva) são de SEGUNDA dimensão. A assertiva cruzou as dimensões.","fundamento":"Doutrina dos direitos humanos — dimensões/gerações.","macete":"1ª Liberdade / 2ª Igualdade / 3ª Fraternidade (solidariedade).","erroComum":"Trocar o conteúdo/valor de cada dimensão.","comoBancaPensa":"Par ordenado dimensão↔valor é alvo clássico de inversão."}},"DH-009":{"cognitivo":{"motivo":"Cobrar os princípios do uso diferenciado da força (Código de Conduta da ONU / princípios básicos).","mede":"Direitos humanos e responsabilidade do Estado (item 3).","pegadinhaDesc":"Item correto; a banca costuma inverter para tornar a arma de fogo regra ou dispensar a proporcionalidade.","ondeErra":"Trata o uso da força como discricionário e ilimitado.","palavraCritica":"excepcional / proporcionalidade","tecnica":"Força: legal + necessária + proporcional. Arma de fogo é último recurso.","regraMental":"Uso da força é escalonado e excepcional — arma de fogo só quando indispensável para proteger a vida."},"comentario":{"resolucao":"CERTO. Os princípios internacionais (Código de Conduta para os Encarregados da Aplicação da Lei e Princípios Básicos sobre o Uso da Força, da ONU) exigem legalidade, necessidade e proporcionalidade, com o emprego de arma de fogo como medida excepcional, voltada à proteção da vida.","fundamento":"Instrumentos internacionais de DH aplicáveis à atividade policial (ONU).","macete":"Força policial: LNP — Legalidade, Necessidade, Proporcionalidade. Arma = último recurso.","erroComum":"Tratar o uso da força como livre ou a arma de fogo como primeira opção.","comoBancaPensa":"Tema operacional de DH: a banca inverte a excepcionalidade da arma de fogo."}},"DH-010":{"cognitivo":{"motivo":"Cobrar o direito à integridade pessoal (art. 5º da CADH).","mede":"Convenção Americana (Dias 03/08 do plano; item 6 do edital).","pegadinhaDesc":"Item correto; a banca costuma restringir a integridade apenas à dimensão física.","ondeErra":"Limita a proteção ao aspecto físico, esquecendo psíquico e moral.","palavraCritica":"física, psíquica e moral","tecnica":"Integridade pessoal na CADH abrange as três dimensões: física, psíquica e moral.","regraMental":"Pacto de São José: integridade é tripla (física + psíquica + moral) e veda tortura/tratos degradantes."},"comentario":{"resolucao":"CERTO. CADH (Decreto 678/1992), art. 5º: toda pessoa tem direito ao respeito de sua integridade física, psíquica e moral, sendo vedada a tortura e as penas ou tratos cruéis, desumanos ou degradantes. Dialoga com o art. 5º, III, da CF.","fundamento":"Decreto 678/1992 (CADH), art. 5º; CF, art. 5º, III.","macete":"Integridade do Pacto = física + psíquica + moral (as três).","erroComum":"Restringir a integridade ao aspecto físico.","comoBancaPensa":"Reduzir o alcance de um direito (só física) é isca comum."}},"DH-011":{"cognitivo":{"motivo":"Cobrar as garantias judiciais da CADH (art. 8º).","mede":"Convenção Americana — garantias judiciais.","pegadinhaDesc":"Item correto; a banca costuma negar o duplo grau como garantia convencional ou omitir o prazo razoável.","ondeErra":"Desconhece que o duplo grau tem previsão convencional expressa.","palavraCritica":"prazo razoável + recurso a tribunal superior","tecnica":"Art. 8º da CADH: presunção de inocência, prazo razoável, ampla defesa e direito de recorrer (duplo grau).","regraMental":"Pacto de São José, art. 8º: julgamento em prazo razoável + duplo grau de jurisdição."},"comentario":{"resolucao":"CERTO. CADH, art. 8º (garantias judiciais): assegura o julgamento em prazo razoável por juiz competente, imparcial e independente, a presunção de inocência e o direito de recorrer da sentença a juiz ou tribunal superior (duplo grau de jurisdição).","fundamento":"Decreto 678/1992 (CADH), art. 8º.","macete":"Art. 8º da CADH = 'pacote de garantias': prazo razoável, inocência, defesa, duplo grau.","erroComum":"Negar o duplo grau como garantia convencional.","comoBancaPensa":"Testa o conhecimento do conteúdo do art. 8º da Convenção."}},"DH-012":{"cognitivo":{"motivo":"Cobrar a cláusula de vedação ao retrocesso quanto à pena de morte (art. 4º da CADH).","mede":"Convenção Americana — direito à vida.","pegadinhaDesc":"A banca costuma afirmar que a CADH proíbe a pena de morte em termos absolutos, para todos os países.","ondeErra":"Confunde vedação ao retrocesso com proibição absoluta universal.","palavraCritica":"não restabelecer nos que aboliram","tecnica":"CADH não proíbe a pena de morte em absoluto — veda seu restabelecimento e ampliação (efeito cliquet).","regraMental":"Pacto de São José: quem aboliu a pena de morte não pode trazê-la de volta (não retrocesso)."},"comentario":{"resolucao":"CERTO. CADH, art. 4º: nos Estados que aboliram a pena de morte, não se pode restabelecê-la, nem estendê-la a novos delitos. Trata-se de cláusula de proibição ao retrocesso (efeito cliquet), e não de proibição universal e absoluta da pena capital.","fundamento":"Decreto 678/1992 (CADH), art. 4º.","macete":"Aboliu a pena de morte? Não pode voltar atrás (não retrocesso).","erroComum":"Tratar a CADH como proibição absoluta da pena de morte.","comoBancaPensa":"Confunde vedação ao retrocesso com proibição universal."}},"DH-013":{"cognitivo":{"motivo":"Cobrar o marco da Declaração Universal de 1948.","mede":"Afirmação histórica dos direitos humanos (item 2 do edital).","pegadinhaDesc":"A banca costuma trocar a data (1945/1966) ou o órgão.","ondeErra":"Confunde a DUDH (1948) com a Carta da ONU (1945) ou os Pactos (1966).","palavraCritica":"1948 / Assembleia Geral da ONU","tecnica":"DUDH: 1948, ONU. Marco da internacionalização dos DH após a 2ª Guerra.","regraMental":"1945 Carta da ONU; 1948 Declaração Universal; 1966 Pactos Internacionais."},"comentario":{"resolucao":"CERTO. A Declaração Universal dos Direitos Humanos (DUDH) foi adotada pela Assembleia Geral da ONU em 10/12/1948, tornando-se o marco da internacionalização e da afirmação histórica dos direitos humanos, base do sistema global de proteção.","fundamento":"História dos direitos humanos — DUDH (1948).","macete":"1945 Carta da ONU → 1948 DUDH → 1966 Pactos. Ordem cronológica.","erroComum":"Trocar a data ou confundir DUDH com a Carta da ONU.","comoBancaPensa":"Datas e marcos históricos são cobrados por troca de ano/documento."}},"DH-014":{"cognitivo":{"motivo":"Cobrar o conceito de universalidade dos DH.","mede":"Teoria geral dos direitos humanos.","pegadinhaDesc":"A banca costuma restringir a universalidade a nacionais ou confundir com indivisibilidade.","ondeErra":"Limita a titularidade dos DH a certos grupos.","palavraCritica":"independentemente de qualquer condição","tecnica":"Universalidade: titularidade a TODOS, pela simples condição humana.","regraMental":"Universal = de todo ser humano. Indivisível = não se fatiam (civis + sociais formam um bloco)."},"comentario":{"resolucao":"CERTO. A universalidade indica que os direitos humanos pertencem a todas as pessoas, pela sua simples condição humana, sem discriminação. Não se confunde com a indivisibilidade (os direitos formam um conjunto integrado).","fundamento":"Teoria geral dos direitos humanos — características.","macete":"Universalidade = 'de todos'. Indivisibilidade = 'em bloco'.","erroComum":"Restringir a titularidade dos DH ou confundir com indivisibilidade.","comoBancaPensa":"Conceitua uma característica trocando-a por outra."}},"DH-015":{"cognitivo":{"motivo":"Cobrar o § 3º do art. 5º da CF (rito de equivalência a emenda).","mede":"A Constituição e os tratados internacionais de DH (item 6 do edital).","pegadinhaDesc":"A banca costuma trocar o quórum (maioria absoluta) ou o número de turnos.","ondeErra":"Confunde o rito do § 3º (3/5, 2 turnos) com o de tratados comuns.","palavraCritica":"3/5, dois turnos, cada Casa","tecnica":"Tratado de DH aprovado por 3/5 em 2 turnos nas duas Casas = status de emenda constitucional (§ 3º).","regraMental":"Rito de emenda (3/5 + 2 turnos) → tratado de DH vira norma constitucional. Sem esse rito → status supralegal."},"comentario":{"resolucao":"CERTO. CF, art. 5º, § 3º (EC 45/2004): tratados e convenções sobre direitos humanos aprovados em cada Casa do Congresso, em dois turnos, por três quintos dos votos, equivalem a emendas constitucionais. Sem esse rito, os tratados de DH têm status supralegal (STF, RE 466.343).","fundamento":"CF, art. 5º, § 3º; STF, RE 466.343.","macete":"3/5 + 2 turnos = status constitucional. Rito comum = supralegal.","erroComum":"Trocar o quórum (3/5) por maioria absoluta.","comoBancaPensa":"Números do rito (3/5, 2 turnos) são o alvo da manipulação."}},"DH-016":{"cognitivo":{"motivo":"Cobrar a relatividade (limitabilidade) dos direitos humanos.","mede":"Características dos direitos humanos (item 1 do edital).","pegadinhaDesc":"Absolutiza os DH, ignorando que são relativos.","ondeErra":"Confunde 'fundamental' com 'ilimitado'.","palavraCritica":"caráter absoluto","tecnica":"DH são relativos: colisões resolvem-se por ponderação/proporcionalidade.","regraMental":"Não há direito humano absoluto (salvo a vedação à tortura, tida como sem exceção)."},"comentario":{"resolucao":"ERRADO. Os direitos humanos são RELATIVOS (limitáveis): em caso de colisão, resolve-se por ponderação e proporcionalidade. A regra é a relatividade — a doutrina aponta como quase única exceção a vedação absoluta à tortura e ao tratamento desumano.","fundamento":"Teoria geral dos direitos humanos; CF, art. 5º, III.","macete":"DH = relativos. 'Absoluto' quase nunca é resposta certa (exceção: vedação à tortura).","erroComum":"Tratar os DH como ilimitados.","comoBancaPensa":"Termo absoluto aplicado a direitos que são relativos."}},"DH-017":{"cognitivo":{"motivo":"Distinguir a DUDH (declaração/resolução) dos tratados de DH.","mede":"A Constituição e os tratados de DH (item 6 do edital).","pegadinhaDesc":"Atribui à DUDH natureza de tratado com status de emenda.","ondeErra":"Confunde declaração (soft law) com tratado formal.","palavraCritica":"tratado / status de emenda (falso)","tecnica":"A DUDH é resolução da Assembleia Geral da ONU (não tratado). Status de emenda é o dos tratados de DH aprovados pelo rito do art. 5º, § 3º.","regraMental":"DUDH = declaração (força moral/costumeira). Status de emenda é de tratado com rito do § 3º (ex.: Convenção de NY sobre PcD)."},"comentario":{"resolucao":"ERRADO. A DUDH (1948) é uma RESOLUÇÃO/DECLARAÇÃO da Assembleia Geral da ONU, não um tratado em sentido formal — embora tenha enorme força moral e seja reconhecida como direito costumeiro internacional. O status de emenda constitucional é reservado aos tratados de DH aprovados pelo rito do art. 5º, § 3º, da CF.","fundamento":"DUDH (1948); CF, art. 5º, § 3º; STF, RE 466.343.","macete":"DUDH = declaração (soft law). Emenda constitucional = tratado com rito do § 3º.","erroComum":"Tratar a DUDH como tratado com força constitucional.","comoBancaPensa":"Confunde a natureza jurídica da DUDH com a dos tratados."}},"DH-018":{"cognitivo":{"motivo":"Cobrar a diferença entre status constitucional (rito do § 3º) e supralegal.","mede":"A Constituição e os tratados de DH (item 6 do edital).","pegadinhaDesc":"Atribui status constitucional a todos os tratados de DH, sem o rito especial.","ondeErra":"Ignora que só o rito do art. 5º, § 3º, confere status de emenda.","palavraCritica":"todos / independentemente do rito (falso)","tecnica":"Tratado de DH com rito do § 3º (3/5, 2 turnos): status constitucional. Sem esse rito: SUPRALEGAL (STF, RE 466.343).","regraMental":"Só com rito de emenda o tratado de DH vira norma constitucional. Senão, supralegal."},"comentario":{"resolucao":"ERRADO. Apenas os tratados de DH aprovados pelo rito do art. 5º, § 3º (dois turnos, 3/5 em cada Casa) equivalem a emendas constitucionais. Os demais tratados de DH têm status SUPRALEGAL (acima da lei, abaixo da Constituição), conforme o STF (RE 466.343).","fundamento":"CF, art. 5º, § 3º; STF, RE 466.343.","macete":"Rito do § 3º = constitucional. Sem ele = supralegal.","erroComum":"Dar status constitucional a todo tratado de DH.","comoBancaPensa":"Generaliza o status constitucional (termo absoluto)."}},"DH-019":{"cognitivo":{"motivo":"Cobrar a vedação do art. 4º da CADH quanto à pena de morte.","mede":"Convenção Americana — direito à vida.","pegadinhaDesc":"Admite pena de morte a menores de 18, o que a CADH proíbe.","ondeErra":"Desconhece as vedações etárias e pessoais do art. 4º.","palavraCritica":"menores de 18 (vedado)","tecnica":"CADH, art. 4º: não se aplica pena de morte a quem, ao tempo do crime, era menor de 18 ou maior de 70 anos, nem a mulheres grávidas.","regraMental":"Pena de morte na CADH: nunca a menores de 18, maiores de 70 e gestantes."},"comentario":{"resolucao":"ERRADO. CADH, art. 4º, item 5: não se pode impor a pena de morte a pessoas que, no momento do delito, tinham menos de 18 anos ou mais de 70 anos, nem a mulheres em estado de gravidez. A previsão em lei interna não afasta a vedação convencional.","fundamento":"Decreto 678/1992 (CADH), art. 4º, item 5.","macete":"Pena de morte na CADH: proibida a <18, >70 e gestantes.","erroComum":"Admitir pena de morte a menor de 18 por lei interna.","comoBancaPensa":"Cria exceção vedada pela Convenção."}},"DH-020":{"cognitivo":{"motivo":"Distinguir a Comissão (não jurisdicional) da Corte Interamericana (jurisdicional).","mede":"Sistema interamericano de proteção (item 6 do edital).","pegadinhaDesc":"Atribui à Comissão a função jurisdicional, que é da Corte.","ondeErra":"Confunde os dois órgãos do sistema interamericano.","palavraCritica":"Comissão como órgão jurisdicional (falso)","tecnica":"Comissão IDH: órgão de promoção/monitoramento (analisa petições, faz recomendações). Corte IDH: órgão JURISDICIONAL (julga e condena).","regraMental":"Comissão recomenda; Corte julga e condena. A Comissão não profere sentença."},"comentario":{"resolucao":"ERRADO. A Comissão Interamericana NÃO é órgão jurisdicional — atua na promoção e defesa dos DH, recebendo petições e formulando recomendações. O órgão jurisdicional é a CORTE Interamericana de Direitos Humanos, competente para julgar e condenar os Estados (função contenciosa e consultiva).","fundamento":"CADH — Comissão (arts. 34 e ss.) e Corte (arts. 52 e ss.).","macete":"Comissão recomenda; Corte condena.","erroComum":"Atribuir função jurisdicional à Comissão.","comoBancaPensa":"Troca as funções da Comissão e da Corte."}},"DH-021":{"cognitivo":{"motivo":"Cobrar a natureza absoluta (inderrogável) da vedação à tortura.","mede":"Convenção Americana e DH na CF (item 6 do edital).","pegadinhaDesc":"Usa um termo absoluto que, excepcionalmente, é VERDADEIRO — punindo quem aplica a heurística cegamente.","ondeErra":"Marca 'errado' por reflexo, ao ver 'caráter absoluto'.","palavraCritica":"absoluto (aqui, correto)","tecnica":"A vedação à tortura é norma inderrogável (jus cogens): não se suspende nem em estados de exceção.","regraMental":"Regra: direitos são relativos. Exceção clássica: vedação à tortura é absoluta."},"comentario":{"resolucao":"CERTO. A vedação à tortura é inderrogável: a CADH (art. 27) não admite a suspensão do art. 5º nem em situações excepcionais, e a CF a trata como garantia insuscetível de relativização (art. 5º, III, e XLIII). Trata-se de norma de jus cogens no direito internacional.","fundamento":"CF, art. 5º, III e XLIII; CADH, arts. 5º e 27; Lei 9.455/1997.","macete":"Quase nada é absoluto — mas a proibição da tortura é.","erroComum":"Marcar E por reflexo ao ver 'absoluto'.","comoBancaPensa":"Planta um termo absoluto VERDADEIRO para punir o atalho sem conteúdo."}},"DH-022":{"cognitivo":{"motivo":"Distinguir as competências da Comissão e da Corte Interamericana.","mede":"Sistema interamericano de proteção (item 6 do edital).","pegadinhaDesc":"Atribui à Comissão a função jurisdicional, que pertence à Corte.","ondeErra":"Confunde os dois órgãos do sistema.","palavraCritica":"Comissão como órgão jurisdicional (falso)","tecnica":"Comissão: recebe petições, investiga, recomenda e pode submeter o caso à Corte. Corte: julga e condena.","regraMental":"Comissão recomenda e 'acusa'; a Corte julga e condena."},"comentario":{"resolucao":"ERRADO. A Comissão Interamericana NÃO é órgão jurisdicional: analisa petições, formula recomendações e pode submeter o caso à Corte. Quem profere sentenças condenatórias contra os Estados é a CORTE Interamericana de Direitos Humanos, órgão jurisdicional do sistema.","fundamento":"CADH — Comissão (arts. 34 e ss.) e Corte (arts. 52 e ss.).","macete":"Comissão recomenda; Corte condena.","erroComum":"Atribuir função jurisdicional à Comissão.","comoBancaPensa":"Troca as funções dos dois órgãos do sistema interamericano."}},"DH-023":{"cognitivo":{"motivo":"Cobrar a regra da prisão civil por dívida na CADH (art. 7.7).","mede":"CADH — direito à liberdade pessoal.","pegadinhaDesc":"A banca pode incluir o depositário infiel como exceção.","ondeErra":"Confunde a exceção alimentar com o caso do depositário infiel.","palavraCritica":"obrigação alimentar","tecnica":"Art. 7.7: ninguém deve ser detido por dívidas, salvo mandado de autoridade competente por inadimplemento de obrigação alimentar.","regraMental":"Prisão civil só por alimentos. Depositário infiel não entra."},"comentario":{"resolucao":"CERTO. O art. 7.7 da CADH veda a prisão civil por dívida, ressalvando unicamente o inadimplemento de obrigação alimentar. Foi com base nesse dispositivo que o STF afastou a prisão do depositário infiel.","fundamento":"CADH (Decreto 678/1992), art. 7.7.","macete":"Prisão civil: só por alimentos.","erroComum":"Incluir o depositário infiel entre as exceções.","comoBancaPensa":"Amplia as exceções à vedação da prisão por dívida."}},"DH-024":{"cognitivo":{"motivo":"Cobrar a Súmula Vinculante 25 do STF.","mede":"CADH — efeitos internos (prisão civil).","pegadinhaDesc":"Afirma como lícita a prisão que o STF considerou ilícita.","ondeErra":"Desconhece a SV 25 e o status supralegal da CADH.","palavraCritica":"lícita","tecnica":"SV 25: é ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade do depósito. A CADH, supralegal, tornou inaplicável a prisão.","regraMental":"Depositário infiel: prisão ILÍCITA (SV 25)."},"comentario":{"resolucao":"ERRADO. Conforme a Súmula Vinculante 25 do STF, é ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade do depósito. O caráter supralegal da CADH (art. 7.7) tornou inaplicável a legislação interna que autorizava essa prisão.","fundamento":"CADH, art. 7.7; STF, Súmula Vinculante 25; RE 466.343.","jurisprudencia":"STF, SV 25; RE 466.343.","macete":"Depositário infiel = prisão ilícita (SV 25).","erroComum":"Considerar lícita a prisão do depositário infiel.","comoBancaPensa":"Inverte o entendimento sumular vinculante."}},"DH-025":{"cognitivo":{"motivo":"Cobrar a teoria do status supralegal (RE 466.343).","mede":"Direitos Humanos — hierarquia dos tratados.","pegadinhaDesc":"A banca pode atribuir status de lei ordinária ou de norma constitucional a todos os tratados.","ondeErra":"Confunde tratados aprovados pelo rito do art. 5º, § 3º (constitucionais) com os demais (supralegais).","palavraCritica":"supralegal","tecnica":"RE 466.343: tratados de DH não aprovados pelo rito do § 3º do art. 5º têm status supralegal (acima da lei, abaixo da CF). Aprovados pelo rito especial → equivalentes a emenda.","regraMental":"DH sem rito de emenda = supralegal. Com rito (§3º) = constitucional."},"comentario":{"resolucao":"CERTO. No RE 466.343, o STF firmou que os tratados internacionais de direitos humanos aprovados sem o rito do art. 5º, § 3º, da CF possuem status supralegal — acima da legislação ordinária, mas abaixo da Constituição. Já os aprovados por aquele rito equivalem a emendas constitucionais.","fundamento":"CF, art. 5º, §§ 2º e 3º; STF, RE 466.343.","jurisprudencia":"STF, RE 466.343.","macete":"Supralegal (regra) × constitucional (rito do § 3º).","erroComum":"Dar a todos os tratados o mesmo status.","comoBancaPensa":"Confunde os dois níveis hierárquicos possíveis."}},"DH-026":{"cognitivo":{"motivo":"Cobrar a literalidade do direito à vida (art. 4.1).","mede":"CADH — direito à vida.","pegadinhaDesc":"A banca pode trocar 'em geral, desde a concepção' por 'desde o nascimento'.","ondeErra":"Não retém a expressão 'em geral, desde a concepção'.","palavraCritica":"desde o momento da concepção","tecnica":"Art. 4.1: toda pessoa tem direito a que se respeite sua vida, protegida pela lei e, em geral, desde o momento da concepção.","regraMental":"CADH: vida protegida, em geral, desde a concepção."},"comentario":{"resolucao":"CERTO. O art. 4.1 da CADH dispõe que toda pessoa tem o direito de que se respeite sua vida, protegida pela lei e, em geral, desde o momento da concepção, não podendo ninguém ser privado da vida arbitrariamente.","fundamento":"CADH, art. 4.1.","macete":"Vida protegida, em geral, desde a concepção.","erroComum":"Trocar por 'desde o nascimento'.","comoBancaPensa":"Altera o marco temporal de proteção."}},"DH-027":{"cognitivo":{"motivo":"Cobrar a vedação de restabelecer a pena de morte (art. 4.3).","mede":"CADH — pena de morte.","pegadinhaDesc":"Admite o restabelecimento da pena de morte, o que a CADH veda.","ondeErra":"Ignora a lógica de não retrocesso da Convenção.","palavraCritica":"restabeleçam","tecnica":"Art. 4.3: não se pode restabelecer a pena de morte nos Estados que a hajam abolido. A CADH segue a lógica de abolição progressiva.","regraMental":"Aboliu a pena de morte? Não pode voltar atrás (não retrocesso)."},"comentario":{"resolucao":"ERRADO. O art. 4.3 da CADH proíbe o restabelecimento da pena de morte nos Estados que a tenham abolido. A Convenção adota a lógica da abolição progressiva e da vedação ao retrocesso, não admitindo sua reinstituição, nem mesmo por lei.","fundamento":"CADH, art. 4.3.","macete":"Aboliu a pena de morte, não retorna.","erroComum":"Admitir o restabelecimento por lei.","comoBancaPensa":"Permite retrocesso vedado pela Convenção."}},"DH-028":{"cognitivo":{"motivo":"Cobrar o duplo grau de jurisdição como garantia convencional (art. 8.2.h).","mede":"CADH — garantias judiciais.","pegadinhaDesc":"A banca pode negar a previsão do duplo grau na CADH.","ondeErra":"Acha que o duplo grau é apenas princípio implícito.","palavraCritica":"recorrer a juiz ou tribunal superior","tecnica":"Art. 8.2.h: garante o direito de recorrer da sentença a juiz ou tribunal superior — base convencional do duplo grau.","regraMental":"Duplo grau é garantia expressa na CADH (art. 8.2.h)."},"comentario":{"resolucao":"CERTO. O art. 8.2.h da CADH assegura, entre as garantias judiciais mínimas, o direito de recorrer da sentença a juiz ou tribunal superior, consagrando o duplo grau de jurisdição no plano convencional.","fundamento":"CADH, art. 8.2.h.","macete":"Duplo grau: garantia expressa da CADH.","erroComum":"Tratar o duplo grau como mero princípio implícito.","comoBancaPensa":"Nega a previsão convencional expressa."}},"DH-029":{"cognitivo":{"motivo":"Cobrar o reconhecimento da jurisdição contenciosa da Corte (art. 62).","mede":"CADH — sistema interamericano.","pegadinhaDesc":"Faz a jurisdição contenciosa decorrer automaticamente da ratificação.","ondeErra":"Confunde ratificação da Convenção com aceitação da competência contenciosa.","palavraCritica":"automaticamente","tecnica":"Art. 62: a competência contenciosa da Corte depende de declaração específica de reconhecimento pelo Estado. O Brasil a reconheceu apenas em 1998 (Decreto Legislativo 89/1998).","regraMental":"Ratificar ≠ aceitar a Corte. A jurisdição contenciosa exige declaração."},"comentario":{"resolucao":"ERRADO. Conforme o art. 62 da CADH, a submissão à jurisdição contenciosa da Corte Interamericana depende de declaração específica de reconhecimento pelo Estado, não decorrendo automaticamente da ratificação da Convenção. O Brasil reconheceu essa competência somente em 1998.","fundamento":"CADH, art. 62; Decreto Legislativo 89/1998.","macete":"Corte contenciosa: só com declaração expressa (Brasil, 1998).","erroComum":"Fazer a jurisdição decorrer da mera ratificação.","comoBancaPensa":"Confunde ratificação com aceitação da competência."}},"DH-030":{"cognitivo":{"motivo":"Cobrar a presunção de inocência convencional (art. 8.2).","mede":"CADH — garantias judiciais.","pegadinhaDesc":"A banca pode negar a previsão ou condicioná-la ao trânsito em julgado no plano interno.","ondeErra":"Confunde a redação da CADH com a da CF.","palavraCritica":"presuma sua inocência","tecnica":"Art. 8.2: presunção de inocência até a comprovação legal da culpa. É garantia judicial mínima.","regraMental":"CADH também consagra a presunção de inocência."},"comentario":{"resolucao":"CERTO. O art. 8.2 da CADH estabelece que toda pessoa acusada de um delito tem direito a que se presuma sua inocência enquanto não se comprove legalmente sua culpa, garantia reforçada no direito interno pelo art. 5º, LVII, da CF.","fundamento":"CADH, art. 8.2; CF, art. 5º, LVII.","macete":"Presunção de inocência: garantia da CADH e da CF.","erroComum":"Negar a previsão convencional.","comoBancaPensa":"Item de fixação (nível fácil)."}},"DH-031":{"cognitivo":{"motivo":"Cobrar a vedação da censura prévia (art. 13).","mede":"CADH — liberdade de pensamento e expressão.","pegadinhaDesc":"Trata a censura prévia como regra, quando a CADH a proíbe.","ondeErra":"Ignora que o controle é a posteriori (responsabilidades ulteriores).","palavraCritica":"meio ordinário","tecnica":"Art. 13: veda a censura prévia, admitindo apenas responsabilidades ulteriores. Exceção limitada: classificação de espetáculos para proteção da infância e adolescência (art. 13.4).","regraMental":"CADH: sem censura prévia. Controle é posterior (responsabilização)."},"comentario":{"resolucao":"ERRADO. O art. 13 da CADH proíbe a censura prévia, admitindo apenas responsabilidades ulteriores fixadas em lei. A única ressalva é a classificação de espetáculos públicos para a proteção moral da infância e da adolescência (art. 13.4). Logo, a censura prévia não é meio ordinário de controle.","fundamento":"CADH, art. 13.","macete":"Sem censura prévia; controle é a posteriori.","erroComum":"Admitir censura prévia como regra.","comoBancaPensa":"Transforma exceção limitada em regra geral."}},"DH-032":{"cognitivo":{"motivo":"Cobrar a proteção da honra e da vida privada (art. 11).","mede":"CADH — proteção da honra e da dignidade.","pegadinhaDesc":"A banca pode restringir a proteção apenas à honra, omitindo a vida privada.","ondeErra":"Não associa a proteção à vedação de ingerências arbitrárias.","palavraCritica":"ingerências arbitrárias","tecnica":"Art. 11: proteção da honra e da dignidade; ninguém pode ser objeto de ingerências arbitrárias na vida privada, família, domicílio ou correspondência.","regraMental":"CADH protege honra + dignidade + vida privada."},"comentario":{"resolucao":"CERTO. O art. 11 da CADH assegura o respeito à honra e o reconhecimento da dignidade, vedando ingerências arbitrárias ou abusivas na vida privada, na família, no domicílio e na correspondência.","fundamento":"CADH, art. 11.","macete":"Honra + dignidade + vida privada protegidas.","erroComum":"Restringir a proteção só à honra.","comoBancaPensa":"Item de fixação (nível fácil)."}},"DH-033":{"cognitivo":{"motivo":"Cobrar a natureza e a estrutura do PNDH-3.","mede":"PNDH-3 — organização.","pegadinhaDesc":"A banca pode dizer que foi instituído por lei ou emenda.","ondeErra":"Confunde o instrumento normativo (decreto) com lei.","palavraCritica":"eixos orientadores","tecnica":"PNDH-3: Decreto 7.037/2009, organizado em 6 eixos orientadores, desdobrados em diretrizes e objetivos estratégicos.","regraMental":"PNDH-3 = decreto + eixos → diretrizes → objetivos."},"comentario":{"resolucao":"CERTO. O PNDH-3 foi instituído pelo Decreto 7.037/2009 e organiza-se em eixos orientadores, que se desdobram em diretrizes e objetivos estratégicos, com ações programáticas atribuídas a diversos órgãos.","fundamento":"Decreto 7.037/2009.","macete":"PNDH-3: decreto, com eixos → diretrizes → objetivos.","erroComum":"Atribuir-lhe natureza de lei ou emenda.","comoBancaPensa":"Troca o instrumento normativo."}},"DH-034":{"cognitivo":{"motivo":"Reforçar a natureza infralegal do PNDH-3.","mede":"PNDH-3 — hierarquia normativa.","pegadinhaDesc":"Eleva o programa a norma constitucional.","ondeErra":"Confunde política pública com norma constitucional.","palavraCritica":"emenda constitucional","tecnica":"O PNDH-3 é ato do Executivo (Decreto 7.037/2009) — não é emenda nem lei; veicula política pública de direitos humanos.","regraMental":"PNDH-3 é decreto, não emenda. Não é norma constitucional."},"comentario":{"resolucao":"ERRADO. O PNDH-3 foi instituído por decreto (7.037/2009), ato normativo do Poder Executivo, e não por emenda constitucional. Não ostenta, portanto, status de norma constitucional: trata-se de instrumento de política pública em direitos humanos.","fundamento":"Decreto 7.037/2009.","macete":"Decreto ≠ emenda. PNDH-3 não é norma constitucional.","erroComum":"Elevar o programa ao nível constitucional.","comoBancaPensa":"Troca o instrumento normativo para inflar a hierarquia."}},"DH-035":{"cognitivo":{"motivo":"Cobrar os eixos orientadores do PNDH-3.","mede":"PNDH-3 — eixos.","pegadinhaDesc":"A banca pode negar que a segurança pública seja um eixo.","ondeErra":"Desconhece a integração entre segurança pública e direitos humanos no programa.","palavraCritica":"segurança pública, acesso à justiça e combate à violência","tecnica":"O Eixo Orientador IV do PNDH-3 trata de 'Segurança Pública, Acesso à Justiça e Combate à Violência'.","regraMental":"Segurança pública é um dos eixos do PNDH-3 (Eixo IV)."},"comentario":{"resolucao":"CERTO. O PNDH-3 contempla, entre seus eixos orientadores, o Eixo IV — Segurança Pública, Acesso à Justiça e Combate à Violência —, articulando a atuação policial com a proteção dos direitos humanos.","fundamento":"Decreto 7.037/2009, Eixo Orientador IV.","macete":"Eixo IV: segurança pública + acesso à justiça + combate à violência.","erroComum":"Negar a segurança pública como eixo do programa.","comoBancaPensa":"Testa o conhecimento dos eixos."}},"DH-036":{"cognitivo":{"motivo":"Cobrar o caráter articulado e participativo do PNDH-3.","mede":"PNDH-3 — abrangência.","pegadinhaDesc":"Restringe o programa ao Executivo federal.","ondeErra":"Ignora a articulação federativa e a participação social.","palavraCritica":"exclusivamente","tecnica":"O PNDH-3 pressupõe articulação entre os entes federativos, os Poderes e a sociedade civil, prevendo participação social na sua implementação e monitoramento.","regraMental":"PNDH-3 é articulado: União, estados, municípios e sociedade civil."},"comentario":{"resolucao":"ERRADO. O PNDH-3 tem caráter articulado e participativo, envolvendo os entes federativos, os Poderes da República e a sociedade civil na sua implementação e monitoramento. Não se dirige exclusivamente ao Executivo federal.","fundamento":"Decreto 7.037/2009.","macete":"PNDH-3 = esforço articulado e participativo, não só federal.","erroComum":"Restringir o programa ao Executivo da União.","comoBancaPensa":"Reduz indevidamente o alcance do programa."}},"DH-037":{"cognitivo":{"motivo":"Cobrar os princípios estruturantes dos direitos humanos no PNDH-3.","mede":"PNDH-3 — princípios.","pegadinhaDesc":"A banca pode negar a interdependência ou trocar por 'divisibilidade'.","ondeErra":"Confunde os atributos clássicos dos direitos humanos.","palavraCritica":"indivisibilidade e interdependência","tecnica":"Direitos humanos são universais, indivisíveis e interdependentes — princípios reafirmados pelo PNDH-3.","regraMental":"DH: universais, indivisíveis e interdependentes."},"comentario":{"resolucao":"CERTO. O PNDH-3 reafirma os princípios da universalidade, da indivisibilidade e da interdependência dos direitos humanos, reconhecendo que direitos civis, políticos, econômicos, sociais, culturais e ambientais formam um todo integrado.","fundamento":"Decreto 7.037/2009.","macete":"DH: universais + indivisíveis + interdependentes.","erroComum":"Trocar 'indivisibilidade' por 'divisibilidade'.","comoBancaPensa":"Testa os atributos clássicos dos direitos humanos."}},"DH-038":{"cognitivo":{"motivo":"Cobrar a abrangência ampla dos direitos humanos no PNDH-3.","mede":"PNDH-3 — dimensão dos direitos.","pegadinhaDesc":"Reduz os direitos humanos apenas à dimensão civil e política.","ondeErra":"Desconhece as dimensões econômica, social, cultural e ambiental.","palavraCritica":"restringem-se","tecnica":"O PNDH-3 abarca direitos civis, políticos, econômicos, sociais, culturais e ambientais, em razão da indivisibilidade dos direitos humanos.","regraMental":"DH não é só civil e político: também econômico, social, cultural e ambiental."},"comentario":{"resolucao":"ERRADO. Em razão da indivisibilidade e da interdependência, o PNDH-3 abrange não apenas os direitos civis e políticos, mas também os econômicos, sociais, culturais e ambientais. Restringi-los aos civis e políticos contraria a perspectiva do programa.","fundamento":"Decreto 7.037/2009.","macete":"DH abarca todas as dimensões, não só a civil/política.","erroComum":"Reduzir os direitos humanos aos civis e políticos.","comoBancaPensa":"Restringe indevidamente a abrangência dos direitos."}},"DH-039":{"cognitivo":{"motivo":"Cobrar a eficácia horizontal dos direitos fundamentais.","mede":"Direitos Humanos/Constitucional — eficácia dos direitos.","pegadinhaDesc":"Restringe a eficácia à dimensão vertical (Estado-indivíduo).","ondeErra":"Desconhece a eficácia horizontal (entre particulares).","palavraCritica":"exclusivamente","tecnica":"O STF reconhece a eficácia horizontal (Drittwirkung): os direitos fundamentais também vinculam as relações privadas, não só as relações com o Estado.","regraMental":"Direitos fundamentais valem também entre particulares (eficácia horizontal)."},"comentario":{"resolucao":"ERRADO. Além da eficácia vertical (Estado-indivíduo), os direitos fundamentais possuem eficácia horizontal, incidindo também nas relações entre particulares, conforme reconhecido pelo STF. Restringi-los à relação com o Estado é incorreto.","fundamento":"STF, RE 201.819 (eficácia horizontal).","jurisprudencia":"STF, RE 201.819.","macete":"Vertical E horizontal: também entre particulares.","erroComum":"Limitar a eficácia à dimensão vertical.","comoBancaPensa":"Restringe indevidamente o alcance dos direitos."}},"DH-040":{"cognitivo":{"motivo":"Cobrar a natureza jurídica da DUDH.","mede":"Direitos Humanos — sistema global.","pegadinhaDesc":"Trata a Declaração como tratado convencional vinculante.","ondeErra":"Confunde Declaração (resolução) com tratado (convenção).","palavraCritica":"tratado internacional","tecnica":"A DUDH é uma RESOLUÇÃO/Declaração da Assembleia Geral da ONU — não é tratado. Sua força hoje advém do costume internacional e do reconhecimento como jus cogens, mas não da natureza convencional.","regraMental":"DUDH = Declaração (resolução), não tratado."},"comentario":{"resolucao":"ERRADO. A DUDH (1948) é uma declaração adotada por resolução da Assembleia Geral da ONU, e não um tratado internacional. Embora tenha enorme força moral e seja considerada norma costumeira/de jus cogens, não é, por si só, um tratado convencional diretamente vinculante.","fundamento":"DUDH/1948; teoria das fontes do Direito Internacional.","macete":"Declaração ≠ tratado. DUDH é resolução da ONU.","erroComum":"Chamar a DUDH de tratado vinculante.","comoBancaPensa":"Troca a natureza jurídica do documento."}},"DH-041":{"cognitivo":{"motivo":"Relacionar garantias do preso na CF e na CADH.","mede":"Direitos Humanos — garantias judiciais.","pegadinhaDesc":"A banca pode negar a previsão em um dos diplomas.","ondeErra":"Desconhece a dupla proteção (interna e convencional).","palavraCritica":"Constituição e Convenção Americana","tecnica":"CF, art. 5º, LXIII (silêncio e assistência de advogado) e CADH, art. 8º (garantias judiciais) protegem essas garantias — dupla fonte.","regraMental":"Silêncio e defesa técnica: garantidos na CF e na CADH."},"comentario":{"resolucao":"CERTO. O direito ao silêncio e à assistência de advogado está previsto no art. 5º, LXIII, da CF e nas garantias judiciais do art. 8º da Convenção Americana de Direitos Humanos, havendo dupla proteção (constitucional e convencional).","fundamento":"CF, art. 5º, LXIII; CADH, art. 8º.","macete":"Garantias do preso: CF + CADH.","erroComum":"Negar a previsão convencional.","comoBancaPensa":"Testa o diálogo entre CF e tratados de DH."}},"DH-042":{"cognitivo":{"motivo":"Cobrar a excepcionalidade do uso de algemas (SV 11).","mede":"Direitos Humanos — dignidade da pessoa presa.","pegadinhaDesc":"Trata o uso de algemas como livre e irrestrito.","ondeErra":"Ignora a exigência de justificativa por escrito.","palavraCritica":"livre ... independentemente de justificativa","tecnica":"Súmula Vinculante 11: o uso de algemas é excepcional, admitido apenas em caso de resistência, fundado receio de fuga ou perigo à integridade, com justificativa por escrito, sob pena de responsabilidade.","regraMental":"Algema é exceção justificada por escrito (SV 11)."},"comentario":{"resolucao":"ERRADO. Conforme a Súmula Vinculante 11 do STF, o uso de algemas é medida excepcional, cabível apenas diante de resistência, fundado receio de fuga ou perigo à integridade física própria ou alheia, exigindo-se justificativa por escrito. Não é livre nem discricionário.","fundamento":"STF, Súmula Vinculante 11.","jurisprudencia":"STF, SV 11.","macete":"Algema: excepcional e justificada por escrito.","erroComum":"Tratar o uso de algemas como regra livre.","comoBancaPensa":"Termo absoluto que ignora a excepcionalidade."}},"DH-043":{"cognitivo":{"motivo":"Aplicar a garantia de comunicação da prisão (art. 5º, LXII).","mede":"Direitos Humanos — proteção contra prisão arbitrária.","pegadinhaDesc":"A banca pode restringir a comunicação apenas ao juiz.","ondeErra":"Esquece a comunicação à família ou pessoa indicada.","palavraCritica":"juiz e à família","tecnica":"Art. 5º, LXII: a prisão de qualquer pessoa será comunicada imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada.","regraMental":"Prisão: comunica ao juiz E à família."},"comentario":{"resolucao":"CERTO. O art. 5º, LXII, da CF exige que a prisão seja comunicada imediatamente ao juiz competente e à família do preso ou a pessoa por ele indicada — garantia contra prisões arbitrárias e desaparecimentos.","fundamento":"CF, art. 5º, LXII.","macete":"Comunicação: juiz + família.","erroComum":"Restringir a comunicação só ao juiz.","comoBancaPensa":"Testa a dupla comunicação."}},"DH-044":{"cognitivo":{"motivo":"Cobrar o direito à apresentação sem demora à autoridade judicial (art. 7.5).","mede":"Direitos Humanos — CADH e audiência de custódia.","pegadinhaDesc":"Nega o direito de apresentação à autoridade judicial.","ondeErra":"Desconhece o fundamento convencional da audiência de custódia.","palavraCritica":"não tem direito","tecnica":"CADH, art. 7.5: toda pessoa presa deve ser conduzida, sem demora, à presença de um juiz — base da audiência de custódia no Brasil.","regraMental":"CADH 7.5: preso vai, sem demora, ao juiz (custódia)."},"comentario":{"resolucao":"ERRADO. O art. 7.5 da CADH assegura que toda pessoa presa seja conduzida, sem demora, à presença de um juiz ou autoridade autorizada por lei a exercer funções judiciais — fundamento da audiência de custódia. Negar esse direito contraria a Convenção.","fundamento":"CADH, art. 7.5.","macete":"Preso → juiz, sem demora (audiência de custódia).","erroComum":"Negar o direito de apresentação ao juiz.","comoBancaPensa":"Restrição indevida de direito convencional."}},"DH-045":{"cognitivo":{"motivo":"Item de CONTROLE: súmula real corretamente citada — não rejeitar por reflexo.","mede":"Direitos Humanos — verificação (não rejeição) de citação.","pegadinhaDesc":"Depois de treinar súmulas inventadas, o candidato tende a rejeitar QUALQUER número.","ondeErra":"Marca E por desconfiança reflexa, sem saber que a SV 11 existe e está correta.","palavraCritica":"Súmula Vinculante 11 (real e corretamente citada)","tecnica":"Nem todo número é armadilha: a SV 11 existe e diz exatamente isso. Verifique — não rejeite no automático.","regraMental":"Desconfiar ≠ rejeitar tudo. Súmula real e correta → C."},"comentario":{"resolucao":"CERTO. A Súmula Vinculante 11 do STF de fato estabelece que o uso de algemas é excepcional, cabível apenas em caso de resistência, fundado receio de fuga ou perigo à integridade física própria ou alheia, exigindo justificativa por escrito, sob pena de responsabilidade. A citação está correta — e reconhecê-la é tão importante quanto rejeitar as súmulas inventadas.","fundamento":"STF, Súmula Vinculante 11.","jurisprudencia":"STF, SV 11.","macete":"Verifique a súmula; se é real e bate, marque C sem medo.","erroComum":"Rejeitar por desconfiança reflexa de qualquer número.","comoBancaPensa":"Após inventar súmulas, cobra uma verdadeira para pegar o candidato hipercauteloso."}},"DH-046":{"cognitivo":{"motivo":"Item de CONTROLE: exigência real do Estatuto dos Refugiados.","mede":"Direitos Humanos — condição de refugiado.","pegadinhaDesc":"A lista de motivos pode parecer restrição inventada.","ondeErra":"Rejeita achando que qualquer motivo de fuga (ex.: econômico) já bastaria.","palavraCritica":"fundado temor de perseguição","tecnica":"Art. 1º da Lei 9.474/1997: a condição de refugiado exige fundado temor de perseguição por raça, religião, nacionalidade, grupo social ou opinião política — motivos econômicos isolados não bastam.","regraMental":"Refúgio: temor fundado de perseguição por um dos 5 motivos taxativos da lei."},"comentario":{"resolucao":"CERTO. O art. 1º da Lei 9.474/1997 exige, para o reconhecimento da condição de refugiado, fundado temor de perseguição por motivos de raça, religião, nacionalidade, grupo social ou opinião política — reproduzindo a Convenção de 1951 sobre o Estatuto dos Refugiados.","fundamento":"Lei 9.474/1997, art. 1º; Convenção de 1951 (Estatuto dos Refugiados).","macete":"Refúgio: 5 motivos taxativos (raça, religião, nacionalidade, grupo social, opinião política).","erroComum":"Admitir motivo puramente econômico como suficiente.","comoBancaPensa":"Reproduz fielmente a exigência real, testando conhecimento, não desconfiança."}},"DH-047":{"cognitivo":{"motivo":"Reproduz o art. 8.1 da CADH, trocando 'independente' por 'vinculado ao Poder Executivo'.","mede":"Direitos Humanos — CADH, garantias judiciais.","pegadinhaDesc":"Mantém quase toda a frase correta; a troca contradiz a própria lógica da garantia.","ondeErra":"Não percebe que 'vinculado ao Executivo' é o oposto de independência judicial.","palavraCritica":"vinculado ao Poder Executivo","tecnica":"Art. 8.1 da CADH exige juiz ou tribunal competente, INDEPENDENTE e imparcial — nunca vinculado a outro Poder.","regraMental":"Garantias judiciais da CADH: juiz independente E imparcial, sempre os dois."},"comentario":{"resolucao":"ERRADO. O art. 8.1 da Convenção Americana de Direitos Humanos assegura o julgamento por juiz ou tribunal competente, INDEPENDENTE e imparcial — a substituição por 'vinculado ao Poder Executivo' contradiz frontalmente a garantia de independência judicial.","fundamento":"CADH, art. 8.1.","macete":"CADH: juiz competente, independente e imparcial — sempre os três atributos.","erroComum":"Não perceber a contradição lógica entre 'vinculado ao Executivo' e independência.","comoBancaPensa":"Substitui um atributo essencial por seu oposto conceitual."}},"DH-048":{"cognitivo":{"motivo":"Cobrar a legitimidade ativa correta para submissão de casos à Corte IDH.","mede":"Direitos Humanos — Sistema Interamericano (CADH).","pegadinhaDesc":"A banca atribui a indivíduos uma legitimidade que a Convenção não confere.","ondeErra":"Confunde o direito de peticionar à Comissão (amplo, de qualquer pessoa) com a legitimidade para submeter casos à Corte (restrita).","palavraCritica":"diretamente à ... Corte","tecnica":"Qualquer pessoa, grupo ou ONG pode peticionar à COMISSÃO Interamericana (art. 44, CADH). Somente os ESTADOS-PARTE e a própria COMISSÃO têm legitimidade para submeter um caso à CORTE Interamericana (art. 61, CADH) — indivíduos não têm acesso direto à Corte.","regraMental":"Petição individual → Comissão. Submissão de caso → Corte (só Estados e Comissão)."},"comentario":{"resolucao":"ERRADO. Indivíduos e grupos de pessoas podem peticionar à Comissão Interamericana de Direitos Humanos (art. 44, CADH), mas não têm legitimidade para submeter casos diretamente à Corte Interamericana — essa legitimidade é restrita aos Estados-parte e à própria Comissão (art. 61, CADH).","fundamento":"Convenção Americana sobre Direitos Humanos (Pacto de São José da Costa Rica), arts. 44 e 61.","macete":"Petição individual vai à Comissão; só Estados/Comissão levam o caso à Corte.","erroComum":"Confundir o amplo direito de petição (Comissão) com a legitimidade restrita para acionar a Corte.","comoBancaPensa":"Cria uma exigência/legitimidade que a Convenção não confere aos particulares."}},"DH-049":{"cognitivo":{"motivo":"Cobrar a ampla legitimidade para peticionar à Comissão Interamericana.","mede":"Direitos Humanos — Sistema Interamericano (CADH).","pegadinhaDesc":"A banca pode restringir essa legitimidade apenas às vítimas diretas.","ondeErra":"Acha que só a própria vítima pode peticionar, ignorando a amplitude do art. 44 da CADH.","palavraCritica":"qualquer pessoa ... Comissão","tecnica":"O art. 44 da CADH confere ampla legitimidade: qualquer pessoa, grupo de pessoas ou ONG reconhecida em Estado-membro da OEA pode peticionar à Comissão, independentemente de ser a própria vítima da violação alegada.","regraMental":"Petição à Comissão: legitimidade ampla, não se restringe à vítima direta."},"comentario":{"resolucao":"CERTO. Nos termos do art. 44 da CADH, a legitimidade para peticionar à Comissão Interamericana de Direitos Humanos é ampla, abrangendo qualquer pessoa, grupo de pessoas ou entidade não governamental legalmente reconhecida em Estado-membro da OEA, independentemente de ser a vítima direta da violação.","fundamento":"Convenção Americana sobre Direitos Humanos (Pacto de São José da Costa Rica), art. 44.","macete":"Art. 44 CADH: legitimidade ampla para peticionar à Comissão.","erroComum":"Restringir a legitimidade apenas à própria vítima da violação.","comoBancaPensa":"Item de fixação sobre a amplitude do direito de petição no sistema interamericano."}},"DH-050":{"cognitivo":{"motivo":"Cobrar o número correto de eixos orientadores do PNDH-3 e a existência do eixo de segurança pública.","mede":"Direitos Humanos — Política Nacional de Direitos Humanos (PNDH-3).","pegadinhaDesc":"A banca troca o número de eixos (seis) por outro (cinco) e nega a existência do eixo de segurança pública.","ondeErra":"Não memoriza o número exato de eixos nem a existência do Eixo IV específico sobre segurança pública.","palavraCritica":"cinco eixos ... não se inclui","tecnica":"O PNDH-3 estrutura-se em SEIS eixos orientadores, entre os quais o Eixo Orientador IV, dedicado especificamente à 'Segurança Pública, Acesso à Justiça e Combate à Violência'.","regraMental":"PNDH-3: 6 eixos. Eixo IV = Segurança Pública, Acesso à Justiça e Combate à Violência."},"comentario":{"resolucao":"ERRADO. O PNDH-3 estrutura-se em SEIS eixos orientadores (e não cinco), sendo o Eixo Orientador IV dedicado especificamente à 'Segurança Pública, Acesso à Justiça e Combate à Violência' — contrariando a dupla afirmação do item.","fundamento":"Decreto nº 7.037/2009 (Programa Nacional de Direitos Humanos — PNDH-3).","macete":"PNDH-3: 6 eixos. Eixo IV trata exatamente de segurança pública.","erroComum":"Errar o número de eixos ou negar a existência do eixo de segurança pública.","comoBancaPensa":"Combina troca numérica com negação de um fato existente, dobrando a chance de erro."}},"DH-051":{"cognitivo":{"motivo":"Cobrar o rito específico exigido para que tratados de direitos humanos equivalham a emendas constitucionais.","mede":"Direitos Humanos — incorporação de tratados internacionais (art. 5º, §3º, CF).","pegadinhaDesc":"A banca troca o quórum e o número de turnos exigidos pela CF por requisitos mais brandos.","ondeErra":"Não memoriza o rito específico exigido (dois turnos, três quintos) e aceita um quórum mais simples.","palavraCritica":"maioria simples ... turno único","tecnica":"Pelo art. 5º, §3º, da CF, os tratados de direitos humanos equivalem a emendas constitucionais apenas quando aprovados, EM CADA CASA do Congresso Nacional, em DOIS TURNOS, por TRÊS QUINTOS dos votos dos respectivos membros — e não por maioria simples em turno único.","regraMental":"Equivalência a emenda: 2 turnos + 3/5 dos votos, em cada Casa (mesmo rito de PEC)."},"comentario":{"resolucao":"ERRADO. O rito exigido pelo art. 5º, §3º, da CF para que o tratado de direitos humanos equivalha a emenda constitucional é: aprovação em CADA Casa do Congresso Nacional, em DOIS turnos, por TRÊS QUINTOS dos votos dos respectivos membros — e não maioria simples em turno único, como afirmado. Os tratados que não observam esse rito, segundo o STF (RE 466.343/SP, rel. Min. Cezar Peluso), possuem status supralegal, e não de lei ordinária.","fundamento":"Constituição Federal, art. 5º, §3º (incluído pela EC nº 45/2004); STF, RE 466.343/SP (status supralegal dos tratados de direitos humanos não incorporados pelo rito qualificado).","macete":"Mesmo rito de uma PEC: 2 turnos, 3/5, em cada Casa.","erroComum":"Confundir com o quórum de aprovação de lei ordinária ou complementar.","comoBancaPensa":"Troca o quórum qualificado exigido pela CF por um requisito mais brando e genérico."}},"DH-052":{"cognitivo":{"motivo":"Cobrar as restrições específicas da CADH à aplicação da pena de morte.","mede":"Direitos Humanos — Sistema Interamericano (CADH, art. 4).","pegadinhaDesc":"A banca pode alterar as idades-limite ou omitir a vedação ao restabelecimento.","ondeErra":"Erra as idades específicas (18 e 70 anos) ou nega a vedação ao restabelecimento da pena.","palavraCritica":"menor de dezoito anos ou maior de setenta anos","tecnica":"Art. 4º da CADH: Estados que aboliram a pena de morte não podem restabelecê-la; a pena não pode ser imposta a quem tinha menos de 18 anos ou mais de 70 anos ao tempo do delito, nem à mulher em estado de gravidez.","regraMental":"CADH art. 4: abolição é irreversível + veda pena de morte para <18, >70 anos e gestantes."},"comentario":{"resolucao":"CERTO. O art. 4º da CADH estabelece exatamente essas três garantias: irreversibilidade da abolição da pena de morte, vedação de sua imposição a quem tinha menos de 18 ou mais de 70 anos ao tempo do delito, e vedação à sua aplicação a mulher em estado de gravidez.","fundamento":"Convenção Americana sobre Direitos Humanos (Pacto de São José da Costa Rica), art. 4º.","macete":"Pena de morte na CADH: nunca para <18, >70 anos ou gestante; abolição é definitiva.","erroComum":"Errar as idades-limite ou esquecer a vedação ao restabelecimento.","comoBancaPensa":"Cobra a memorização literal e completa de um dispositivo central da Convenção."}},"DH-053":{"cognitivo":{"motivo":"Cobrar as duas competências da Corte IDH e a legitimidade restrita para a via contenciosa.","mede":"Direitos Humanos — Sistema Interamericano (competências da Corte IDH).","pegadinhaDesc":"A banca pode negar uma das duas competências ou ampliar indevidamente a legitimidade ativa.","ondeErra":"Confunde a competência consultiva com a contenciosa, ou amplia a legitimidade para indivíduos.","palavraCritica":"apenas os Estados-parte e a Comissão","tecnica":"A Corte IDH tem competência CONTENCIOSA (julgar casos concretos de violação) e CONSULTIVA (emitir pareceres interpretativos, inclusive sobre outros tratados). Apenas Estados-parte e a Comissão podem submeter casos à via contenciosa (art. 61, CADH).","regraMental":"Corte IDH: contenciosa (julga) + consultiva (opina). Só Estados/Comissão acionam a via contenciosa."},"comentario":{"resolucao":"CERTO. A Corte Interamericana exerce competência contenciosa (julgamento de casos concretos de violação da Convenção) e competência consultiva (emissão de pareceres sobre a interpretação de tratados de direitos humanos), sendo que apenas os Estados-parte e a Comissão Interamericana têm legitimidade para submeter casos à via contenciosa, conforme o art. 61 da CADH.","fundamento":"Convenção Americana sobre Direitos Humanos (Pacto de São José da Costa Rica), arts. 61 a 64.","macete":"Corte IDH: contenciosa (julga) + consultiva (opina); legitimidade contenciosa restrita a Estados/Comissão.","erroComum":"Achar que indivíduos podem acionar diretamente a via contenciosa da Corte.","comoBancaPensa":"Consolida, em um único item correto, a distinção testada de forma invertida no item anterior."}},"DH-054":{"cognitivo":{"motivo":"Mostrar que há regras constitucionais genuinamente absolutas.","mede":"CF, art. 5º, III — núcleo inderrogável.","pegadinhaDesc":"O 'qualquer exceção' aciona o reflexo de marcar ERRADO, mas aqui a vedação é mesmo absoluta.","ondeErra":"Marca ERRADO por reflexo ao ver termo absoluto, sem checar se a regra comporta exceção.","palavraCritica":"qualquer exceção","tecnica":"Termo absoluto não é sinônimo de item falso. A vedação à tortura é cláusula pétrea sem ressalva, inclusive em estado de sítio.","regraMental":"Tortura: proibição absoluta, sem exceção — nem em guerra."},"comentario":{"resolucao":"CERTO. O art. 5º, III, da CF não admite ressalva: a vedação à tortura e ao tratamento desumano ou degradante é absoluta, não sendo suspensa nem durante estado de defesa ou de sítio. É também norma imperativa de direito internacional (jus cogens).","fundamento":"CF, art. 5º, III; art. 5º, XLIII; Convenção contra a Tortura (ONU).","macete":"Tortura não tem exceção.","erroComum":"Marcar ERRADO só porque o item usa termo absoluto.","comoBancaPensa":"Pune quem decorou 'palavra absoluta = errado' sem verificar a norma."}},"DH-055":{"cognitivo":{"motivo":"Fixar o rol do art. 5º, XLIII, como regra sem exceção.","mede":"CF, art. 5º, XLIII.","pegadinhaDesc":"'Em todos os casos' soa exagerado, mas reproduz o comando constitucional.","ondeErra":"Presume que deve haver exceção por causa do termo totalizante.","palavraCritica":"em todos os casos","tecnica":"O inciso XLIII é taxativo quanto a esses quatro grupos: inafiançáveis e insuscetíveis de graça ou anistia, sem ressalva.","regraMental":"3TH: Tortura, Tráfico, Terrorismo e Hediondos — sem fiança, graça ou anistia."},"comentario":{"resolucao":"CERTO. O art. 5º, XLIII, da CF determina que a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos. Não há exceção constitucional a esse regime.","fundamento":"CF, art. 5º, XLIII.","macete":"Tortura, Tráfico, Terrorismo, Hediondos.","erroComum":"Rejeitar o item pelo 'em todos os casos'.","comoBancaPensa":"Testa se o candidato conhece o rol ou apenas reage ao advérbio."}},"DH-056":{"cognitivo":{"motivo":"Fixar o pareamento entre dimensão, conteúdo e postura estatal.","mede":"Teoria dos direitos humanos — dimensões.","pegadinhaDesc":"Três elementos corretamente pareados em cada dimensão.","ondeErra":"Inverte a exigência de abstenção e prestação.","palavraCritica":"abstenção ... prestações positivas","tecnica":"Siga o lema francês: 1ª liberdade (Estado se abstém), 2ª igualdade (Estado age), 3ª fraternidade (titularidade coletiva).","regraMental":"Liberdade, igualdade, fraternidade — nessa ordem."},"comentario":{"resolucao":"CERTO. Os direitos de primeira dimensão são os civis e políticos, de matriz liberal, que exigem prestação negativa do Estado; os de segunda dimensão são os sociais, econômicos e culturais, que reclamam atuação positiva. Os de terceira dimensão, ligados à fraternidade, têm titularidade difusa.","fundamento":"Teoria das dimensões dos direitos fundamentais.","macete":"Liberdade, igualdade, fraternidade.","erroComum":"Inverter abstenção e prestação.","comoBancaPensa":"Pareamento correto que exige domínio real da classificação."}}});
